1	/**
2	 * Public API endpoint — joins a customer to the waitlist from the storefront widget.
3	 *
4	 * Called from the theme app extension block when a zip code check fails and
5	 * the merchant has enabled the waitlist feature.
6	 *
7	 * POST /api/waitlist
8	 * Body: { shop: string, zip: string, email: string }
9	 *
10	 * Response:
11	 *   200 { success: true, message: "..." }
12	 *   400 { error: "..." }
13	 *   500 { error: "..." }
14	 */
15	import type { ActionFunctionArgs, LoaderFunctionArgs } from "react-router";
16	import db from "../db.server";
17	import { getShopSubscription } from "../billing.server";
18	import { UNLIMITED } from "../plans";
19	import { normalizeZipCode } from "../utils/zip";
20	import {
21	  sendWaitlistConfirmation,
22	  sendMerchantWaitlistAlert,
23	  type EmailOptions,
24	} from "../email.server";
25	import { rateLimit, getClientIp, rateLimitResponse } from "../utils/rate-limit.server";
26	
27	const CORS_HEADERS = {
28	  "Access-Control-Allow-Origin": "*",
29	  "Access-Control-Allow-Methods": "POST, OPTIONS",
30	  "Access-Control-Allow-Headers": "Content-Type",
31	  "Content-Type": "application/json",
32	};
33	
34	// Handle CORS preflight
35	export const loader = async ({ request }: LoaderFunctionArgs) => {
36	  if (request.method === "OPTIONS") {
37	    return new Response(null, { status: 204, headers: CORS_HEADERS });
38	  }
39	  return new Response(JSON.stringify({ error: "Method not allowed" }), {
40	    status: 405,
41	    headers: CORS_HEADERS,
42	  });
43	};
44	
45	export const action = async ({ request }: ActionFunctionArgs) => {
46	  if (request.method === "OPTIONS") {
47	    return new Response(null, { status: 204, headers: CORS_HEADERS });
48	  }
49	
50	  if (request.method !== "POST") {
51	    return new Response(JSON.stringify({ error: "Method not allowed" }), {
52	      status: 405,
53	      headers: CORS_HEADERS,
54	    });
55	  }
56	
57	  // Rate limit: 10 signups per IP per minute (write operation — tighter limit)
58	  const ip = getClientIp(request);
59	  const { limited, resetAt } = rateLimit(`waitlist:${ip}`, 10, 60_000);
60	  if (limited) return rateLimitResponse(resetAt, CORS_HEADERS);
61	
62	  let shop: string | null = null;
63	  let zip: string | null = null;
64	  let email: string | null = null;
65	  let name: string | null = null;
66	
67	  try {
68	    const body = await request.json();
69	    shop = body?.shop ?? null;
70	    zip = body?.zip ?? null;
71	    email = body?.email ?? null;
72	    name = body?.name ?? null;
73	  } catch {
74	    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
75	      status: 400,
76	      headers: CORS_HEADERS,
77	    });
78	  }
79	
80	  if (!shop || !zip || !email) {
81	    return new Response(
82	      JSON.stringify({ error: "Missing required fields: shop, zip, email" }),
83	      { status: 400, headers: CORS_HEADERS },
84	    );
85	  }
86	
87	  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
88	  if (!/^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/.test(shop) || shop.length > 100) {
89	    return new Response(
90	      JSON.stringify({ error: "Invalid shop parameter" }),
91	      { status: 400, headers: CORS_HEADERS },
92	    );
93	  }
94	
95	  // Enforce input length limits to prevent abuse
96	  if (zip.length > 20 || email.length > 254) {
97	    return new Response(
98	      JSON.stringify({ error: "Invalid input" }),
99	      { status: 400, headers: CORS_HEADERS },
100	    );
101	  }
102	
103	  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
104	    return new Response(
105	      JSON.stringify({ error: "Invalid email address" }),
106	      { status: 400, headers: CORS_HEADERS },
107	    );
108	  }
109	
110	  // Check if shop's plan allows waitlist
111	  try {
112	    const subscription = await getShopSubscription(shop);
113	    if (subscription.limits.maxWaitlist === 0) {
114	      return new Response(
115	        JSON.stringify({ error: "Waitlist is not available on this store's plan" }),
116	        { status: 400, headers: CORS_HEADERS },
117	      );
118	    }
119	    // Enforce entry limit for Starter plan
120	    if (subscription.limits.maxWaitlist < UNLIMITED) {
121	      const currentCount = await db.waitlistEntry.count({ where: { shop } });
122	      if (currentCount >= subscription.limits.maxWaitlist) {
123	        return new Response(
124	          JSON.stringify({ error: "Waitlist is currently full. Please try again later." }),
125	          { status: 400, headers: CORS_HEADERS },
126	        );
127	      }
128	    }
129	  } catch {
130	    // If subscription check fails, deny the request to prevent plan bypass
131	    return new Response(
132	      JSON.stringify({ error: "Unable to verify subscription. Please try again later." }),
133	      { status: 503, headers: CORS_HEADERS },
134	    );
135	  }
136	
137	  try {
138	    const normalizedZip = normalizeZipCode(zip);
139	
140	    await db.waitlistEntry.upsert({
141	      where: {
142	        shop_email_zipCode: {
143	          shop,
144	          email,
145	          zipCode: normalizedZip,
146	        },
147	      },
148	      create: {
149	        shop,
150	        email,
151	        name: name ? name.trim().substring(0, 100) : null,
152	        zipCode: normalizedZip,
153	        status: "waiting",
154	      },
155	      update: {
156	        status: "waiting",
157	      },
158	    });
159	
160	    // Fire-and-forget: fetch email settings then send emails
161	    db.shopSettings
162	      .findUnique({ where: { shop } })
163	      .then((settings) => {
164	        const emailOpts: EmailOptions = {
165	          senderName: settings?.emailSenderName,
166	          shopDisplayName: settings?.shopName,
167	          replyTo: settings?.emailReplyTo,
168	        };
169	
170	        // Confirmation to customer
171	        sendWaitlistConfirmation(email, normalizedZip, shop, emailOpts).catch(() => {});
172	
173	        // Notify merchant if notificationEmail is set
174	        if (settings?.notificationEmail) {
175	          sendMerchantWaitlistAlert(
176	            settings.notificationEmail,
177	            email,
178	            normalizedZip,
179	            shop,
180	            emailOpts,
181	          ).catch(() => {});
182	        }
183	      })
184	      .catch(() => {});
185	
186	    return new Response(
187	      JSON.stringify({
188	        success: true,
189	        message: "You've been added to the waitlist!",
190	      }),
191	      { status: 200, headers: CORS_HEADERS },
192	    );
193	  } catch {
194	    return new Response(
195	      JSON.stringify({ error: "Failed to join waitlist. Please try again." }),
196	      { status: 500, headers: CORS_HEADERS },
197	    );
198	  }
199	};
200

1	/**
2	 * Public API endpoint for the storefront zip code widget.
3	 *
4	 * Called from the merchant's storefront (Theme App Extension or custom JS)
5	 * to check whether a zip code is serviceable.
6	 *
7	 * GET/POST /api/zip-check?shop=store.myshopify.com&zip=12345
8	 *
9	 * Response:
10	 *   200 { allowed: true,  message: "...", eta: "...", zone: "..." }
11	 *   200 { allowed: false, message: "..." }
12	 *   400 { error: "Missing shop or zip parameter" }
13	 *   404 { allowed: false, message: "Zip code not found", notFound: true }
14	 */
15	import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
16	import db from "../db.server";
17	import { normalizeZipCode } from "../utils/zip";
18	import { rateLimit, getClientIp, rateLimitResponse } from "../utils/rate-limit.server";
19	import { getProductCollections } from "../utils/product-collections.server";
20	
21	function calculateDeliveryDate(
22	  estimatedDays: string,
23	  daysOfWeek: string | null,
24	): string | null {
25	  const match = estimatedDays.match(/^(\d+)/);
26	  if (!match) return null;
27	  const minDays = parseInt(match[1], 10);
28	  if (isNaN(minDays) || minDays < 0) return null;
29	
30	  const deliveryDayNames = daysOfWeek
31	    ? daysOfWeek.split(",").map((d) => d.trim().toLowerCase())
32	    : ["mon", "tue", "wed", "thu", "fri"];
33	
34	  const dayMap: Record<string, number> = {
35	    sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6,
36	  };
37	  const deliveryDayNumbers = new Set(
38	    deliveryDayNames.map((d) => dayMap[d]).filter((n) => n !== undefined),
39	  );
40	
41	  if (deliveryDayNumbers.size === 0) {
42	    [1, 2, 3, 4, 5].forEach((d) => deliveryDayNumbers.add(d));
43	  }
44	
45	  const date = new Date();
46	  let businessDaysAdded = 0;
47	
48	  while (businessDaysAdded < minDays) {
49	    date.setDate(date.getDate() + 1);
50	    if (deliveryDayNumbers.has(date.getDay())) {
51	      businessDaysAdded++;
52	    }
53	  }
54	
55	  while (!deliveryDayNumbers.has(date.getDay())) {
56	    date.setDate(date.getDate() + 1);
57	  }
58	
59	  return date.toISOString().split("T")[0];
60	}
61	
62	const CORS_HEADERS = {
63	  "Access-Control-Allow-Origin": "*",
64	  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
65	  "Access-Control-Allow-Headers": "Content-Type",
66	  "Content-Type": "application/json",
67	};
68	
69	// Applied only to successful (allowed) ZIP check responses to reduce DB load
70	// for repeated lookups of the same ZIP code from the same storefront visitor.
71	const SUCCESS_HEADERS = {
72	  ...CORS_HEADERS,
73	  "Cache-Control": "public, max-age=60, stale-while-revalidate=120",
74	};
75	
76	// Short cache for denied/not-found responses so merchants see changes quickly
77	// (e.g. when they add a new ZIP code it takes effect within 5 seconds).
78	const DENY_HEADERS = {
79	  ...CORS_HEADERS,
80	  "Cache-Control": "no-cache, max-age=5",
81	};
82	
83	const SHOP_DOMAIN_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;
84	
85	/**
86	 * Returns true if a delivery rule's geographic constraints (zone or explicit
87	 * zip codes) match the given normalized zip and its zone.
88	 * Product/collection rules can optionally layer geographic constraints on top.
89	 * A rule with no zone and no zipCodes matches all geographies.
90	 */
91	function matchesZipOrZone(
92	  rule: { zipCodes: string | null; zone: string | null },
93	  normalizedZip: string,
94	  zipZone: string | null,
95	): boolean {
96	  if (rule.zipCodes?.trim()) {
97	    const zips = rule.zipCodes.split(",").map((z) => z.trim().toUpperCase());
98	    return zips.includes(normalizedZip);
99	  }
100	  if (rule.zone) {
101	    return rule.zone === zipZone;
102	  }
103	  // No geographic constraint — matches everywhere
104	  return true;
105	}
106	
107	async function handleZipCheck(
108	  shop: string | null,
109	  zip: string | null,
110	  productId?: string | null,
111	) {
112	  if (!shop || !zip) {
113	    return new Response(
114	      JSON.stringify({ error: "Missing shop or zip parameter" }),
115	      { status: 400, headers: CORS_HEADERS },
116	    );
117	  }
118	
119	  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
120	  if (!SHOP_DOMAIN_RE.test(shop) || shop.length > 100) {
121	    return new Response(
122	      JSON.stringify({ error: "Invalid shop parameter" }),
123	      { status: 400, headers: CORS_HEADERS },
124	    );
125	  }
126	
127	  // Enforce input length limits to prevent abuse
128	  if (zip.length > 20) {
129	    return new Response(
130	      JSON.stringify({ error: "Invalid zip code" }),
131	      { status: 400, headers: CORS_HEADERS },
132	    );
133	  }
134	
135	  const normalizedZip = normalizeZipCode(zip);
136	
137	  try {
138	  const zipRecord = await db.zipCode.findUnique({
139	    where: { shop_zipCode: { shop, zipCode: normalizedZip } },
140	  });
141	
142	  // Fetch widget config for custom messages (falls back to defaults)
143	  const widgetConfig = await db.widgetConfig.findUnique({ where: { shop } });
144	
145	  // Fetch shop settings to determine default behavior for unlisted zip codes
146	  const shopSettings = await db.shopSettings.findUnique({ where: { shop } });
147	  const defaultBehavior = shopSettings?.defaultBehavior ?? "block";
148	
149	  if (!zipRecord || !zipRecord.isActive) {
150	    const notFoundMsg =
151	      widgetConfig?.notFoundMessage ??
152	      "We currently do not ship to this ZIP code.";
153	
154	    // If the zip is simply not in the list (not inactive) and the merchant
155	    // has set defaultBehavior to "allow", treat it as an allowed zip
156	    if (!zipRecord && defaultBehavior === "allow") {
157	      const successMsg =
158	        widgetConfig?.successMessage ?? "We deliver to your area!";
159	      db.zipCheckLog.create({ data: { shop, zipCode: normalizedZip, result: "defaulted_allow", productId: productId ?? null } }).catch(() => {});
160	      return new Response(
161	        JSON.stringify({
162	          allowed: true,
163	          message: successMsg,
164	          eta: null,
165	          zone: null,
166	          codAvailable: null,
167	          returnPolicy: null,
168	          showWaitlist: false,
169	          waitlistCount: 0,
170	          cutoffTime: null,
171	          daysOfWeek: null,
172	        }),
173	        { status: 200, headers: SUCCESS_HEADERS },
174	      );
175	    }
176	
177	    // Social proof: count how many customers are waiting for this ZIP
178	    let waitlistCount = 0;
179	    try {
180	      waitlistCount = await db.waitlistEntry.count({
181	        where: { shop, zipCode: normalizedZip, status: "waiting" },
182	      });
183	    } catch {
184	      waitlistCount = 0;
185	    }
186	
187	    if (!zipRecord) {
188	      db.zipCheckLog.create({ data: { shop, zipCode: normalizedZip, result: "not_found", productId: productId ?? null } }).catch(() => {});
189	      return new Response(
190	        JSON.stringify({
191	          allowed: false,
192	          message: notFoundMsg,
193	          notFound: true,
194	          showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
195	          waitlistCount,
196	        }),
197	        { status: 200, headers: DENY_HEADERS },
198	      );
199	    }
200	
201	    // Inactive zip — treat same as not found regardless of defaultBehavior
202	    db.zipCheckLog.create({ data: { shop, zipCode: normalizedZip, result: "not_found", productId: productId ?? null } }).catch(() => {});
203	    return new Response(
204	      JSON.stringify({
205	        allowed: false,
206	        message: notFoundMsg,
207	        notFound: true,
208	        showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
209	        waitlistCount,
210	      }),
211	      { status: 200, headers: DENY_HEADERS },
212	    );
213	  }
214	
215	  if (zipRecord.type === "blocked") {
216	    const errorMsg =
217	      zipRecord.message ??
218	      widgetConfig?.errorMessage ??
219	      "Sorry, we don't deliver to this area yet.";
220	
221	    // Social proof: count how many customers are waiting for this ZIP
222	    let waitlistCount = 0;
223	    try {
224	      waitlistCount = await db.waitlistEntry.count({
225	        where: { shop, zipCode: normalizedZip, status: "waiting" },
226	      });
227	    } catch {
228	      waitlistCount = 0;
229	    }
230	
231	    db.zipCheckLog.create({ data: { shop, zipCode: normalizedZip, result: "blocked", productId: productId ?? null } }).catch(() => {});
232	    return new Response(
233	      JSON.stringify({
234	        allowed: false,
235	        message: errorMsg,
236	        showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
237	        waitlistCount,
238	      }),
239	      { status: 200, headers: DENY_HEADERS },
240	    );
241	  }
242	
243	  // Fetch the most relevant active DeliveryRule for this zip.
244	  // Priority 1: rules that explicitly list this zip in their zipCodes field.
245	  // Priority 2: rules that match by zone (with no explicit zip list).
246	  // Within each priority tier, order by `priority ASC` (lower = higher priority).
247	  const zipCodeUpper = normalizedZip;
248	  const zipZone = zipRecord.zone ?? null;
249	
250	  // Fetch all active rules for the shop ordered by priority so we can apply
251	  // the matching logic in a single query result.
252	  const activeRules = await db.deliveryRule.findMany({
253	    where: { shop, isActive: true },
254	    orderBy: { priority: "asc" },
255	  });
256	
257	  let matchedRule: (typeof activeRules)[number] | null = null;
258	
259	  if (productId) {
260	    // Pass 1: product-specific rules — targetType "products", productIds contains this product
261	    for (const rule of activeRules) {
262	      if (rule.targetType === "products" && rule.productIds) {
263	        const ids = rule.productIds.split(",").map((id) => id.trim());
264	        if (ids.includes(productId)) {
265	          if (matchesZipOrZone(rule, zipCodeUpper, zipZone)) {
266	            matchedRule = rule;
267	            break;
268	          }
269	        }
270	      }
271	    }
272	
273	    // Pass 2: collection-specific rules — only run if collection-targeted rules exist
274	    if (!matchedRule) {
275	      const hasCollectionRules = activeRules.some(
276	        (r) => r.targetType === "collections",
277	      );
278	      if (hasCollectionRules) {
279	        const productCollections = await getProductCollections(shop, productId);
280	        for (const rule of activeRules) {
281	          if (rule.targetType === "collections" && rule.collectionIds) {
282	            const ruleCollectionIds = rule.collectionIds
283	              .split(",")
284	              .map((id) => id.trim());
285	            if (ruleCollectionIds.some((cid) => productCollections.includes(cid))) {
286	              if (matchesZipOrZone(rule, zipCodeUpper, zipZone)) {
287	                matchedRule = rule;
288	                break;
289	              }
290	            }
291	          }
292	        }
293	      }
294	    }
295	  }
296	
297	  // Pass 3: explicit zip match on general rules (targetType "all")
298	  if (!matchedRule) {
299	    for (const rule of activeRules) {
300	      if (rule.targetType === "all" && rule.zipCodes) {
301	        const zips = rule.zipCodes.split(",").map((z) => z.trim().toUpperCase());
302	        if (zips.includes(zipCodeUpper)) {
303	          matchedRule = rule;
304	          break;
305	        }
306	      }
307	    }
308	  }
309	
310	  // Pass 4: zone match on general rules — rule's zone matches and no explicit zip list
311	  if (!matchedRule && zipZone) {
312	    for (const rule of activeRules) {
313	      if (
314	        rule.targetType === "all" &&
315	        rule.zone === zipZone &&
316	        (!rule.zipCodes || rule.zipCodes.trim() === "")
317	      ) {
318	        matchedRule = rule;
319	        break;
320	      }
321	    }
322	  }
323	
324	  // Allowed
325	  const successMsg =
326	    zipRecord.message ??
327	    widgetConfig?.successMessage ??
328	    "Great news! We deliver to your area.";
329	
330	  // ETA: prefer the zip-level eta, then fall back to the matched delivery rule's
331	  // estimatedDays so merchants only need to populate one place.
332	  const etaValue = zipRecord.eta ?? matchedRule?.estimatedDays ?? null;
333	
334	  const estimatedDeliveryDate =
335	    widgetConfig?.showDeliveryDate !== false && etaValue
336	      ? calculateDeliveryDate(etaValue, matchedRule?.daysOfWeek ?? null)
337	      : null;
338	
339	  const rawDeliveryFee = widgetConfig?.showDeliveryFee !== false ? (matchedRule?.deliveryFee ?? null) : null;
340	  const deliveryFeeValue = rawDeliveryFee != null && rawDeliveryFee >= 0 ? rawDeliveryFee : null;
341	  const rawFreeShippingAbove = widgetConfig?.showDeliveryFee !== false ? (matchedRule?.freeShippingAbove ?? null) : null;
342	  const freeShippingAboveValue = rawFreeShippingAbove != null && rawFreeShippingAbove >= 0 ? rawFreeShippingAbove : null;
343	
344	  db.zipCheckLog.create({ data: { shop, zipCode: normalizedZip, result: "allowed", productId: productId ?? null } }).catch(() => {});
345	  return new Response(
346	    JSON.stringify({
347	      allowed: true,
348	      message: successMsg,
349	      eta: widgetConfig?.showEta ? etaValue : null,
350	      zone: widgetConfig?.showZone ? (zipRecord.zone ?? null) : null,
351	      codAvailable: widgetConfig?.showCod !== false ? (zipRecord.codAvailable ?? null) : null,
352	      returnPolicy: widgetConfig?.showReturnPolicy !== false ? (zipRecord.returnPolicy ?? null) : null,
353	      showWaitlist: false,
354	      waitlistCount: 0,
355	      cutoffTime: widgetConfig?.showCutoffTime !== false ? (matchedRule?.cutoffTime ?? null) : null,
356	      daysOfWeek: widgetConfig?.showDeliveryDays !== false ? (matchedRule?.daysOfWeek ?? null) : null,
357	      estimatedDeliveryDate,
358	      deliveryFee: deliveryFeeValue,
359	      freeShippingAbove: freeShippingAboveValue,
360	    }),
361	    { status: 200, headers: SUCCESS_HEADERS },
362	  );
363	  } catch (err) {
364	    console.error("[api.zip-check] Unhandled error for shop=%s zip=%s:", shop, zip, err);
365	    return new Response(
366	      JSON.stringify({ error: "Internal server error" }),
367	      { status: 500, headers: CORS_HEADERS },
368	    );
369	  }
370	}
371	
372	// Rate limit: 60 requests per IP per minute (generous for storefront widget)
373	function checkRateLimit(request: Request): Response | null {
374	  const ip = getClientIp(request);
375	  const { limited, resetAt } = rateLimit(`zip-check:${ip}`, 60, 60_000);
376	  if (limited) return rateLimitResponse(resetAt, CORS_HEADERS);
377	  return null;
378	}
379	
380	// Handle GET requests: ?shop=...&zip=...
381	export const loader = async ({ request }: LoaderFunctionArgs) => {
382	  const url = new URL(request.url);
383	
384	  // Handle CORS preflight
385	  if (request.method === "OPTIONS") {
386	    return new Response(null, { status: 204, headers: CORS_HEADERS });
387	  }
388	
389	  const blocked = checkRateLimit(request);
390	  if (blocked) return blocked;
391	
392	  const shop = url.searchParams.get("shop");
393	  const zip = url.searchParams.get("zip");
394	  const product = url.searchParams.get("product");
395	  return handleZipCheck(shop, zip, product);
396	};
397	
398	// Handle POST requests with JSON body: { shop, zip }
399	export const action = async ({ request }: ActionFunctionArgs) => {
400	  const blocked = checkRateLimit(request);
401	  if (blocked) return blocked;
402	
403	  let shop: string | null = null;
404	  let zip: string | null = null;
405	
406	  let product: string | null = null;
407	
408	  try {
409	    const body = await request.json();
410	    shop = body?.shop ?? null;
411	    zip = body?.zip ?? null;
412	    product = body?.product ?? null;
413	  } catch {
414	    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
415	      status: 400,
416	      headers: CORS_HEADERS,
417	    });
418	  }
419	
420	  return handleZipCheck(shop, zip, product);
421	};
