1	/**
2	 * product-collections.server.ts
3	 *
4	 * Resolves which Shopify collections a product belongs to.
5	 * Used by the ZIP check API to match collection-targeted delivery rules.
6	 *
7	 * Caches results in ProductCollectionCache with a 6-hour TTL to avoid
8	 * hitting the Shopify Admin API on every ZIP check request.
9	 */
10	
11	import db from "../db.server";
12	import { unauthenticated } from "../shopify.server";
13	
14	const CACHE_TTL_MS = 6 * 60 * 60 * 1000; // 6 hours
15	
16	/**
17	 * Returns the numeric Shopify collection IDs for a given product.
18	 * Checks DB cache first; falls back to Shopify GraphQL API on cache miss.
19	 * Returns an empty array on any error (graceful degradation to general rules).
20	 */
21	export async function getProductCollections(
22	  shop: string,
23	  productId: string,
24	): Promise<string[]> {
25	  const sixHoursAgo = new Date(Date.now() - CACHE_TTL_MS);
26	
27	  // Check cache first
28	  const cached = await db.productCollectionCache.findMany({
29	    where: {
30	      shop,
31	      productId,
32	      cachedAt: { gt: sixHoursAgo },
33	    },
34	    select: { collectionId: true },
35	  });
36	
37	  if (cached.length > 0) {
38	    return cached.map((c) => c.collectionId);
39	  }
40	
41	  // Cache miss — fetch from Shopify API
42	  try {
43	    const collectionIds = await fetchProductCollectionsFromShopify(
44	      shop,
45	      productId,
46	    );
47	
48	    // Upsert cache entries (handles concurrent requests gracefully)
49	    if (collectionIds.length > 0) {
50	      await Promise.all(
51	        collectionIds.map((collectionId) =>
52	          db.productCollectionCache.upsert({
53	            where: {
54	              shop_productId_collectionId: { shop, productId, collectionId },
55	            },
56	            create: { shop, productId, collectionId },
57	            update: { cachedAt: new Date() },
58	          }),
59	        ),
60	      );
61	    }
62	
63	    // Clean up stale entries for this product (product may have been removed
64	    // from collections since last cache — old entries would give false positives)
65	    await db.productCollectionCache.deleteMany({
66	      where: {
67	        shop,
68	        productId,
69	        cachedAt: { lt: sixHoursAgo },
70	      },
71	    });
72	
73	    return collectionIds;
74	  } catch (error) {
75	    console.error(
76	      "[product-collections] Failed to fetch collections for product",
77	      productId,
78	      "shop",
79	      shop,
80	      error,
81	    );
82	    // Return empty array — ZIP check falls through to general rules
83	    return [];
84	  }
85	}
86	
87	interface ShopifyCollectionNode {
88	  id: string;
89	}
90	
91	interface ShopifyProductCollectionsResponse {
92	  data?: {
93	    product?: {
94	      collections?: {
95	        nodes?: ShopifyCollectionNode[];
96	      };
97	    };
98	  };
99	}
100	
101	async function fetchProductCollectionsFromShopify(
102	  shop: string,
103	  productId: string,
104	): Promise<string[]> {
105	  const { admin } = await unauthenticated.admin(shop);
106	
107	  const response = await admin.graphql(
108	    `#graphql
109	    query ProductCollections($id: ID!) {
110	      product(id: $id) {
111	        collections(first: 50) {
112	          nodes {
113	            id
114	          }
115	        }
116	      }
117	    }`,
118	    {
119	      variables: {
120	        id: `gid://shopify/Product/${productId}`,
121	      },
122	    },
123	  );
124	
125	  const data = (await response.json()) as ShopifyProductCollectionsResponse;
126	  const nodes = data?.data?.product?.collections?.nodes ?? [];
127	
128	  // Extract numeric IDs from GIDs: "gid://shopify/Collection/123456" → "123456"
129	  return nodes
130	    .map((c) => {
131	      const match = c.id.match(/\/(\d+)$/);
132	      return match ? match[1] : null;
133	    })
134	    .filter((id): id is string => id !== null);
135	}
