39	/**
40	 * Returns true if the Resend API key is configured and the client can be
41	 * initialized. Callers use this to show actionable diagnostics in the UI
42	 * (e.g. "API key missing" vs "send failed") without attempting a live send.
43	 */
44	export function isEmailConfigured(): boolean {
45	  return Boolean(process.env.RESEND_API_KEY);
