111	
112	export async function sendWaitlistConfirmation(
113	  to: string,
114	  zipCode: string,
115	  shop: string,
116	  options?: EmailOptions,
117	): Promise<boolean> {
118	  const resend = getClient();
119	  if (!resend) return false;
120	
121	  const name = options?.senderName?.trim() || shopFallbackName(shop, options);
122	
123	  try {
124	    await resend.emails.send({
125	      from: buildFrom(shop, options),
126	      to,
127	      subject: `You're on the waitlist — ${name}`,
128	      html: emailLayout(name, `
129	          <h2 style="margin:0 0 16px;color:#1a1a1a">You're on the waitlist!</h2>
130	          <p style="color:#374151;line-height:1.6">Thanks for signing up. We'll let you know as soon as delivery is available to <strong>${zipCode}</strong>.</p>
131	          <p style="color:#6b7280;font-size:13px;margin-top:24px">— ${name}</p>
132	      `),
133	      text: `You're on the waitlist!\n\nThanks for signing up. We'll let you know as soon as delivery is available to ${zipCode}.\n\n— ${name}`,
134	      ...buildReplyTo(options),
135	    });
136	    return true;
137	  } catch (error) {
138	    console.error("[email] Failed to send waitlist confirmation:", error);
139	    return false;
140	  }
141	}
